for id in pairs(COST) do D.confirmed[id] = true end
local pc
for _, c in ipairs(D.cats) do if c[1] == "PvP" then pc = c end end
if not pc then return end
local function Page(name) for _, p in ipairs(pc[2]) do if p[1] == name then return p end end end
