for _, p in ipairs(pc[2]) do
	for _, g in ipairs(p[3]) do
		if g[2] == 3 then for x = 1, #g[4], 2 do local c = COST[g[4][x]]; if c then g[4][x + 1] = c end end end
	end
end
for _, a in ipairs(ADD) do
	local p = Page(a[1])
	if p then p[3][#p[3] + 1] = { "Also sold on WoW Forever", 3, a[2], a[3] } end
end
